parameters.jsCode:
// 1. Trích xuất text phản hồi từ Gemini
const responseText = $input.first().json.candidates[0].content.parts[0].text;
const aiData = JSON.parse(responseText);

// 2. Lấy lại postId được gửi từ Webhook ban đầu
const webhookData = $('Webhook').first().json.body;

// 3. Ghép prompt tiếng Anh vào Pollinations.ai API (Agent 2)
const promptEncoded = encodeURIComponent(aiData.image_prompt);
const bannerUrl = `https://image.pollinations.ai/prompt/${promptEncoded}?width=1200&height=630&nologo=true`;

// 4. Định dạng bài viết PR hoàn chỉnh
const fullContent = `${aiData.headline}\n\n${aiData.body}\n\n👉 ${aiData.cta}\n\n${aiData.hashtags.join(' ')}`;

return {
  json: {
    postId: webhookData.postId,
    headline: aiData.headline,
    body: aiData.body,
    cta: aiData.cta,
    hashtags: aiData.hashtags,
    fullContent: fullContent,
    imagePrompt: aiData.image_prompt,
    bannerUrl: bannerUrl
  }
};
